import { MakeLogicType, actions, afterMount, connect, kea, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { signalsFeaturesList } from 'products/signals/frontend/generated/api'
import type { InboxFeatureReportApi } from 'products/signals/frontend/generated/api.schemas'

export type FeatureListStage = 'live' | 'staged'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureListLogicValues {
    currentProjectId: number | string // teamLogic
    features: InboxFeatureReportApi[]
    featuresLoading: boolean
    hasMoreLive: boolean
    hasMoreStaged: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureListLogicActions {
    loadFeatures: () => any
    loadFeaturesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadFeaturesSuccess: (
        features: InboxFeatureReportApi[],
        payload?: any
    ) => {
        features: InboxFeatureReportApi[]
        payload?: any
    }
    loadMoreFeatures: ({ stage }: { stage: FeatureListStage }) => {
        stage: FeatureListStage
    }
    loadMoreFeaturesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadMoreFeaturesSuccess: (
        features: InboxFeatureReportApi[],
        payload?: {
            stage: FeatureListStage
        }
    ) => {
        features: InboxFeatureReportApi[]
        payload?: {
            stage: FeatureListStage
        }
    }
    setHasMore: (
        stage: FeatureListStage,
        hasMore: boolean
    ) => {
        hasMore: boolean
        stage: FeatureListStage
    }
}

export type featureListLogicType = MakeLogicType<featureListLogicValues, featureListLogicActions>

/**
 * Loads long-lived feature reports for the Features tab. Creation starts the feature's planning phase.
 */
export const featureListLogic = kea<featureListLogicType>([
    path(['scenes', 'inbox', 'logics', 'featureListLogic']),

    connect(() => ({
        values: [teamLogic, ['currentProjectId']],
    })),

    actions({ setHasMore: (stage: FeatureListStage, hasMore: boolean) => ({ stage, hasMore }) }),
    reducers({
        hasMoreLive: [false, { setHasMore: (state, { stage, hasMore }) => (stage === 'live' ? hasMore : state) }],
        hasMoreStaged: [false, { setHasMore: (state, { stage, hasMore }) => (stage === 'staged' ? hasMore : state) }],
    }),
    loaders(({ values, actions }) => ({
        features: [
            [] as InboxFeatureReportApi[],
            {
                loadFeatures: async () => {
                    const stages = ['live', 'staged'] as const
                    const pages = await Promise.all(
                        stages.map(async (stage) => {
                            const limit = Math.max(
                                100,
                                values.features.filter(
                                    (feature) => (feature.feature_stage === 'staged') === (stage === 'staged')
                                ).length
                            )
                            const response = await signalsFeaturesList(String(values.currentProjectId), {
                                stage,
                                limit,
                            })
                            actions.setHasMore(stage, !!response.next)
                            return response.results
                        })
                    )
                    return pages.flat()
                },
                loadMoreFeatures: async ({ stage }: { stage: FeatureListStage }) => {
                    const existing = values.features
                    const offset = existing.filter(
                        (feature) => (feature.feature_stage === 'staged') === (stage === 'staged')
                    ).length
                    const response = await signalsFeaturesList(String(values.currentProjectId), {
                        stage,
                        limit: 100,
                        offset,
                    })
                    actions.setHasMore(stage, !!response.next)
                    return [...existing, ...response.results]
                },
            },
        ],
    })),

    afterMount(({ actions }) => {
        actions.loadFeatures()
    }),
])
